import {
  Component,
  h,
  Prop,
  EventEmitter,
  Event,
  Watch,
  State,
  ComponentInterface,
  Host,
  Element,
} from '@stencil/core';
import { registerPluginManager } from '@src/shared/unclassified/plugin';
import { createOpenCloseMotion } from '@src/shared/animation';
import { sendActionTracking, sendExposeTracking } from '@src/shared/unclassified/tracking';
import { ArrowPaginationValue, GlobalAlertItem } from '../types';
import { noop } from 'lodash-es';
import { DetailArgs } from '@src/shared/dom';
import { Slot, Slots, Uncontrollable } from '@src/framework/decorators';

/**
 * @slot closeIcon - The close icon slot.
 */
@Component({
  tag: 'ks-multiple-global-alert',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsMultipleGlobalAlert implements ComponentInterface {
  @Element() el!: HTMLKsMultipleGlobalAlertElement;
  /** An array of global alert items to display. Each item provides `variant`, `title`, `content`, and `actions` for one alert state. */
  @Prop() items!: GlobalAlertItem[];
  /** Indicates whether the global alert group is currently open. When `true`, the alerts are displayed. */
  @Prop() open?: boolean;
  /** Indicates whether the global alert group is open by default. */
  @Prop() defaultOpen = true;
  /** Indicates whether to show an icon for each global alert item. When `true`, an icon is displayed. */
  @Prop() showIcon = true;
  /** Indicates whether each global alert item shows a close button. When `true`, a close button is displayed. */
  @Prop() closeable = true;
  /** Whether to enable animation when the global alert group opens or closes. */
  @Prop() animation = true;
  /** Callback triggered after the global alert group finishes closing. */
  @Prop() afterClose?: () => void;
  /** Custom event triggered when an alert item is closed. Emits the closed item and its index. */
  @Event({ bubbles: false, composed: false }) ksItemClose!: EventEmitter<DetailArgs<[GlobalAlertItem, number]>>;

  @Slot({ slotname: 'closeIcon' }) private closeIconSlot?: Slots;

  @Uncontrollable('open', 'defaultOpen', null) @State() mergedOpen?: boolean;
  /** Control the actual animation and visibility of global alert */
  @State() _open: boolean = this.open ?? this.defaultOpen;

  private openAnimation = createOpenCloseMotion();

  @State() currentIndex = 0;

  @Watch('mergedOpen')
  async handleWatch(mergedOpen: boolean) {
    if (!this.animation) {
      this.openAnimation.cancel();
      this._open = mergedOpen;
      return;
    }

    await this.openAnimation.fade(this.el, mergedOpen, {
      duration: 200,
      beforeOpen: () => (this._open = true),
      afterOpen: () => sendExposeTracking(this.el, { eventType: 'visible' }),
      afterClose: () => {
        this._open = false;
        this.afterClose?.();
      },
    });
  }

  @Watch('items')
  handleItemsChange(items?: GlobalAlertItem[]) {
    this.updateDynamicSlots();

    if (this.currentIndex && this.currentIndex >= (items || []).length) {
      this.currentIndex = (items || []).length - 1;
    }
    if (items && items.length === 0) {
      this.mergedOpen = false;
      sendActionTracking(this.el, { eventType: 'close' });
    }
  }

  @Watch('currentIndex')
  handleCurrentIndexChange() {
    this.updateDynamicSlots();
  }

  constructor() {
    registerPluginManager(this.el);
  }

  componentWillLoad() {
    this._open = this.open ?? this.defaultOpen;
  }

  disconnectedCallback() {
    this.openAnimation.dispose();
  }

  // TODO react buggy timing behavior
  componentDidLoad() {
    this.updateDynamicSlots();
  }

  private wrapWithSlot: (slotName: string, children: unknown) => unknown = noop;
  private setDynamicRenderDeps: (items: unknown[]) => void = noop;

  private getCurrentItem(items = this.items) {
    if (!items) {
      return undefined;
    }

    const { currentIndex } = this;

    return items[currentIndex];
  }

  private updateDynamicSlots = () => {
    const dynamicSlots = [];

    const item = this.getCurrentItem();
    if (item) {
      item.title && dynamicSlots.push(this.wrapWithSlot(`title-${this.currentIndex}`, item.title));
      item.content && dynamicSlots.push(this.wrapWithSlot(`content-${this.currentIndex}`, item.content));
      item.actions && dynamicSlots.push(this.wrapWithSlot(`actions-${this.currentIndex}`, item.actions));
    }

    this.setDynamicRenderDeps(dynamicSlots);
  };

  private handleChange({ detail }: CustomEvent<ArrowPaginationValue>) {
    const maxIndex = Math.max((this.items?.length || 0) - 1, 0);
    this.currentIndex =
      detail === 'left' ? Math.max(this.currentIndex - 1, 0) : Math.min(this.currentIndex + 1, maxIndex);
  }

  render() {
    const item = this.getCurrentItem();
    return (
      <Host class="KsMultipleGlobalAlert" role="alert" hidden={!this._open}>
        <ks-global-alert
          open
          onKsClose={() => {
            if (item) {
              this.ksItemClose.emit(DetailArgs(item, this.currentIndex));
            }
          }}
          variant={item?.variant || 'info'}
          showIcon={this.showIcon}
          closeable={this.closeable}
          data-testid="ks-multiple-global-alert-index-badDeg"
        >
          <ks-arrow-pagination
            slot="_internal-pagination"
            infinite={false}
            count={this.items?.length}
            currentIndex={this.currentIndex + 1}
            onKsChange={this.handleChange.bind(this)}
            data-testid="ks-multiple-global-alert-index-uDtKi9"
          ></ks-arrow-pagination>

          {this.closeIconSlot && <slot slot="closeIcon" name="closeIcon" />}

          <slot slot="title" name={`title-${this.currentIndex}`} />
          <slot slot="actions" name={`actions-${this.currentIndex}`} />
          <slot slot="content" name={`content-${this.currentIndex}`} />
        </ks-global-alert>
      </Host>
    );
  }
}
